// ===== Настройки пинов =====
const int BTN_PIN = 2;    // Кнопка
const int LED_PIN = 8;    // Светодиод
const int BUZ_PIN = 9;    // Пассивный зуммер (спикер)

// ===== Частоты нот (в Гц) =====
#define NOTE_C4  262
#define NOTE_D4  294
#define NOTE_E4  330
#define NOTE_F4  349
#define NOTE_G4  392
#define NOTE_A4  440
#define NOTE_B4  494
#define NOTE_C5  523
#define NOTE_D5  587
#define NOTE_E5  659
#define NOTE_F5  698
#define NOTE_G5  784

// ===== Мелодия (We Wish You a Merry Christmas) =====
// Ноты (0 означает паузу)
int melody[] = {
  NOTE_G4, NOTE_G4, NOTE_A4, NOTE_G4, NOTE_C5, NOTE_B4, 0,
  NOTE_G4, NOTE_G4, NOTE_A4, NOTE_G4, NOTE_D5, NOTE_C5, 0,
  NOTE_G4, NOTE_G4, NOTE_G5, NOTE_E5, NOTE_C5, NOTE_B4, NOTE_A4, 0,
  NOTE_F5, NOTE_F5, NOTE_E5, NOTE_C5, NOTE_D5, NOTE_C5, 0
};

// Длительность нот: 4 = четвертная (обычная), 8 = восьмая (быстрая), 2 = половинная (длинная)
int durations[] = {
  4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 2, 4
};

bool lastButtonState = HIGH;
unsigned long lastDebounceTime = 0;
const unsigned long debounceDelay = 50; 

void setup() {
  pinMode(BTN_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZ_PIN, OUTPUT);

  digitalWrite(LED_PIN, LOW);
  digitalWrite(BUZ_PIN, LOW);
  Serial.begin(115200);
}

void loop() {
  bool reading = digitalRead(BTN_PIN);

  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > debounceDelay) {
    // Если кнопка нажата
    if (reading == LOW) {
      Serial.println("Играем мелодию!");
      playMelody(); // Запускаем функцию проигрывания
    }
  }
  lastButtonState = reading;
}

// ===== Функция для проигрывания мелодии =====
void playMelody() {
  digitalWrite(LED_PIN, HIGH); // Включаем светодиод на время мелодии

  // Вычисляем количество нот в массиве
  int numNotes = sizeof(melody) / sizeof(melody[0]);

  for (int i = 0; i < numNotes; i++) {
    // Длительность ноты в миллисекундах (1000 / значение, умноженное на темп)
    int noteDuration = 1000 / durations[i];

    // Если нота не пауза (не 0), играем её
    if (melody[i] != 0) {
      tone(BUZ_PIN, melody[i], noteDuration);
    }

    // Ждем, пока нота играет (с небольшой паузой между нотами для четкости)
    delay(noteDuration * 1.30); 

    // Выключаем звук перед следующей нотой
    noTone(BUZ_PIN);
  }

  digitalWrite(LED_PIN, LOW); // Выключаем светодиод после мелодии
}
